class QuorumQueue:
    def __init__(self, replicas):
        self.replicas = replicas
        self.leader = replicas[0]

    def failover(self):
        available = [r for r in self.replicas if r != self.leader]
        if len(available) >= (len(self.replicas) // 2):
            self.leader = available[0]
            return self.leader
        raise RuntimeError("No quorum")

queue = QuorumQueue(["a", "b", "c"])
print(queue.failover())

from dataclasses import dataclass
from typing import Callable

@dataclass
class Step:
    run: Callable[[], None]
    compensate: Callable[[], None]

completed = []
steps = [
    Step(lambda: print("reserve inventory"), lambda: print("release inventory")),
    Step(lambda: print("charge payment"), lambda: print("refund payment")),
]

try:
    for step in steps:
        step.run()
        completed.append(step)
except Exception:
    for step in reversed(completed):
        step.compensate()

