from dataclasses import dataclass
from time import monotonic

@dataclass
class CircuitBreaker:
    failures: int = 0
    opened_at: float = 0
    threshold: int = 3
    timeout: float = 5

    def call(self, operation):
        if self.opened_at and monotonic() - self.opened_at < self.timeout:
            raise RuntimeError("circuit open")
        try:
            result = operation()
            self.failures = 0
            self.opened_at = 0
            return result
        except Exception:
            self.failures += 1
            if self.failures >= self.threshold:
                self.opened_at = monotonic()
            raise

breaker = CircuitBreaker()
print(breaker.call(lambda: "dependency response"))

