const limit = component => {
  const metrics = component.metrics;
  return metrics.concurrentRequests >= metrics.maxConcurrentRequests
    ? {throttle:true, reason:"concurrency"}
    : metrics.cpuUtilization >= metrics.maxCpuUtilization
      ? {throttle:true, reason:"cpu"}
      : {throttle:false};
};

